import{_ as t,o as r,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Projets divers","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects-diverse/index.md","filePath":"fr/projects-diverse/index.md","lastUpdated":1793123188000}'),a={name:"fr/projects-diverse/index.md"};function o(n,e,l,u,d,p){return r(),s("div",null,[...e[0]||(e[0]=[i('<p><a id="misc-projets"></a><a id="statut"></a></p><h1 id="diverse-projekte" tabindex="-1">Projets divers <a class="header-anchor" href="#diverse-projekte" aria-label="Permalink to &quot;Projets divers {#diverse-projekte}&quot;">​</a></h1><p>Cette page rassemble d&#39;autres projets open source UGSo qui ne font pas directement partie des outils C# ou des applications MQTT.</p><h2 id="ultimate-timer" tabindex="-1">Ultimate Timer <a class="header-anchor" href="#ultimate-timer" aria-label="Permalink to &quot;Ultimate Timer {#ultimate-timer}&quot;">​</a></h2><p><strong>Ultimate Timer</strong></p><p>Un « blueprint » d&#39;automatisation pour Home Assistant permettant de créer des minuteurs réutilisables, dotés d&#39;une logique d&#39;arrêt (STOP) robuste, d&#39;un état « terminé » (DONE) persistant, d&#39;une prise en charge multi-instance et d&#39;une option de fonctionnement via MQTT.</p><ul><li><a href="/fr/projects/ultimate-timer/">Ouvrir la documentation d&#39;Ultimate-Timer</a></li><li><a href="https://github.com/rockbaer2007/ha-ultimate-timer-blueprint" target="_blank" rel="noreferrer">Ouvrir le Blueprint sur GitHub</a></li></ul><h2 id="home-assistant-blueprints" tabindex="-1">Blueprints Home Assistant <a class="header-anchor" href="#home-assistant-blueprints" aria-label="Permalink to &quot;Blueprints Home Assistant {#home-assistant-blueprints}&quot;">​</a></h2><p><strong>Blueprints Home Assistant</strong></p><p>Une petite collection de Blueprints Home Assistant personnalisés, conçus pour la gestion des associations, des groupes de cibles et des fonctions d&#39;arrêt d&#39;urgence. Elle comprend des Blueprints pour relier une source à un maximum de six cibles, une source à un groupe de cibles personnalisable, ainsi qu&#39;une automatisation d&#39;arrêt d&#39;urgence qui désactive des cibles sélectionnées lors du passage de <code>on</code> à <code>off</code>.</p><ul><li><p>Association 1 vers 6 : une source permet d&#39;activer et de désactiver simultanément jusqu&#39;à six cibles.</p></li><li><p>Association source vers groupe de cibles : une source permet de contrôler des entités, des appareils ou des zones choisis librement.</p></li><li><p>Arrêt d&#39;urgence (source désactivée vers cibles désactivées) : lors du passage de la source de <code>on</code> à <code>off</code>, les cibles sélectionnées sont désactivées.</p></li><li><p>Le fichier README sur GitHub contient des boutons d&#39;importation directe vers Home Assistant pour tous les Blueprints inclus.</p></li><li><p><a href="https://github.com/rockbaer2007/homeassistant-blueprints" target="_blank" rel="noreferrer">Ouvrir les Blueprints sur GitHub</a></p></li></ul><h2 id="weitere-projektbereiche" tabindex="-1">Autres domaines de projet <a class="header-anchor" href="#weitere-projektbereiche" aria-label="Permalink to &quot;Autres domaines de projet {#weitere-projektbereiche}&quot;">​</a></h2><ul><li><a href="/fr/projects/">Ouvrir les projets C#</a></li><li><a href="/fr/projects-mqtt/">Ouvrir les projets MQTT</a></li><li><a href="/fr/projects/atlas/">Ouvrir ATLAS</a></li></ul>',13)])])}const h=t(a,[["render",o]]);export{m as __pageData,h as default};
